-- Accounts, sessions, cloud saves, the gallery, sample packs and moderation.
-- Ids are short random strings generated by the server. Timestamps are always
-- written by the server (millisecond precision) so pagination cursors compare
-- exactly.

CREATE TABLE users (
  id           text PRIMARY KEY,
  handle       text NOT NULL UNIQUE,
  display_name text NOT NULL,
  bio          text NOT NULL DEFAULT '',
  avatar_url   text,
  is_admin     boolean NOT NULL DEFAULT false,
  banned_at    timestamptz,
  created_at   timestamptz NOT NULL
);

CREATE TABLE identities (
  provider         text NOT NULL,
  provider_user_id text NOT NULL,
  user_id          text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  PRIMARY KEY (provider, provider_user_id)
);
CREATE INDEX identities_user ON identities (user_id);

-- OAuth round trips in flight. Only hashes are stored.
CREATE TABLE oauth_states (
  state_hash text PRIMARY KEY,
  provider   text NOT NULL,
  redirect   text NOT NULL,
  expires_at timestamptz NOT NULL
);

-- One-time codes handed to the app in the URL fragment after sign-in.
CREATE TABLE auth_codes (
  code_hash  text PRIMARY KEY,
  user_id    text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  expires_at timestamptz NOT NULL
);

CREATE TABLE sessions (
  token_hash text PRIMARY KEY,
  user_id    text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL
);
CREATE INDEX sessions_user ON sessions (user_id);

CREATE TABLE projects (
  id         text PRIMARY KEY,
  user_id    text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  name       text NOT NULL,
  version    integer NOT NULL,
  size       bigint NOT NULL,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL
);
CREATE INDEX projects_user ON projects (user_id, updated_at DESC);

CREATE TABLE project_versions (
  project_id  text NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
  n           integer NOT NULL,
  size        bigint NOT NULL,
  storage_key text NOT NULL,
  created_at  timestamptz NOT NULL,
  PRIMARY KEY (project_id, n)
);

CREATE TABLE beats (
  id          text PRIMARY KEY,
  user_id     text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  title       text NOT NULL,
  description text NOT NULL DEFAULT '',
  tags        text[] NOT NULL DEFAULT '{}',
  genre       text,
  bpm         integer,
  key         text,
  size        bigint NOT NULL,
  storage_key text NOT NULL,
  remix_of    text REFERENCES beats (id) ON DELETE SET NULL,
  remix_root  text REFERENCES beats (id) ON DELETE SET NULL,
  plays       integer NOT NULL DEFAULT 0,
  likes       integer NOT NULL DEFAULT 0,
  hidden_at   timestamptz,
  created_at  timestamptz NOT NULL,
  updated_at  timestamptz NOT NULL
);
CREATE INDEX beats_new ON beats (created_at DESC, id DESC);
CREATE INDEX beats_top ON beats (likes DESC, id DESC);
CREATE INDEX beats_plays ON beats (plays DESC, id DESC);
CREATE INDEX beats_user ON beats (user_id);
CREATE INDEX beats_remix_of ON beats (remix_of);
CREATE INDEX beats_tags ON beats USING gin (tags);

CREATE TABLE beat_likes (
  beat_id    text NOT NULL REFERENCES beats (id) ON DELETE CASCADE,
  user_id    text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL,
  PRIMARY KEY (beat_id, user_id)
);
CREATE INDEX beat_likes_user ON beat_likes (user_id);

-- Last counted play per beat and client. The client is a keyed hash of the
-- address, never the address itself.
CREATE TABLE beat_plays (
  beat_id     text NOT NULL REFERENCES beats (id) ON DELETE CASCADE,
  client_hash text NOT NULL,
  played_at   timestamptz NOT NULL,
  PRIMARY KEY (beat_id, client_hash)
);
CREATE INDEX beat_plays_age ON beat_plays (played_at);

CREATE TABLE packs (
  id           text PRIMARY KEY,
  user_id      text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  name         text NOT NULL,
  description  text NOT NULL DEFAULT '',
  license      text NOT NULL,
  license_url  text NOT NULL,
  attribution  text NOT NULL DEFAULT '',
  tags         text[] NOT NULL DEFAULT '{}',
  published_at timestamptz,
  hidden_at    timestamptz,
  created_at   timestamptz NOT NULL,
  updated_at   timestamptz NOT NULL
);
CREATE INDEX packs_published ON packs (published_at DESC, id DESC);
CREATE INDEX packs_user ON packs (user_id);

CREATE TABLE pack_samples (
  id          text PRIMARY KEY,
  pack_id     text NOT NULL REFERENCES packs (id) ON DELETE CASCADE,
  name        text NOT NULL,
  format      text NOT NULL,
  size        bigint NOT NULL,
  duration_ms integer,
  channels    integer,
  sample_rate integer,
  storage_key text NOT NULL,
  created_at  timestamptz NOT NULL
);
CREATE INDEX pack_samples_pack ON pack_samples (pack_id, created_at, id);

CREATE TABLE reports (
  id              text PRIMARY KEY,
  reporter_id     text NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  target_type     text NOT NULL,
  target_id       text NOT NULL,
  reason          text NOT NULL,
  details         text NOT NULL DEFAULT '',
  status          text NOT NULL DEFAULT 'open',
  resolution      text,
  resolution_note text,
  resolved_by     text,
  resolved_at     timestamptz,
  created_at      timestamptz NOT NULL
);
CREATE UNIQUE INDEX reports_one_open ON reports (reporter_id, target_type, target_id) WHERE status = 'open';
CREATE INDEX reports_status ON reports (status, created_at DESC, id DESC);

-- What admins did. Handles are copied in so the log survives account deletion.
CREATE TABLE audit_log (
  id           bigserial PRIMARY KEY,
  admin_id     text NOT NULL,
  admin_handle text NOT NULL,
  action       text NOT NULL,
  target_type  text NOT NULL,
  target_id    text NOT NULL,
  note         text NOT NULL DEFAULT '',
  created_at   timestamptz NOT NULL
);
